// C++: src/messaging.h toit::MessageEncoder::write_uint8
void MessageEncoder_write_uint8(MessageEncoder *self, uint8 value)
//@ requires ext_encoder(self, ?b, ?cap, ?c, ?k, ?copies) &*& (b == 0 || c + 1 <= cap) &*& c + 1 <= 1000;
//@ ensures ext_encoder(self, b, cap, c + 1, k, copies);
{
  //@ open ext_encoder(self, b, cap, c, k, copies);
  if (!MessageEncoder_encoding_for_size(self)) {
    self->buffer_[self->cursor_] = value;
  }
  self->cursor_++;
  //@ close ext_encoder(self, b, cap, c + 1, k, copies);
}

// C++: src/messaging.cc toit::MessageEncoder::write_cardinal
void MessageEncoder_write_cardinal(MessageEncoder *self, uword value)
//@ requires ext_encoder(self, ?b, ?cap, ?c, ?k, ?copies) &*& (b == 0 || c + card_len(value) <= cap) &*& c + 10 <= 1000;
//@ ensures ext_encoder(self, b, cap, c + card_len(value), k, copies);
{
  //@ int j = 0;
  //@ uword v0 = value;
  while (value >= 128)
  //@ invariant ext_encoder(self, b, cap, c + j, k, copies) &*& 0 <= j &*& j + card_len(value) == card_len(v0) &*& card_len(v0) <= 10;
  {
    //@ card_len_step(value);
    //@ div_rem_nonneg(value, 128);
    MessageEncoder_write_uint8(self, (uint8)(value % 128 + 128));
    //@ shiftright_div(value, succ(succ(succ(succ(succ(succ(succ(zero))))))));
    value >>= 7;
    //@ j++;
  }
  MessageEncoder_write_uint8(self, (uint8)value);
}

// C++: src/messaging.cc toit::MessageEncoder::write_pointer
void MessageEncoder_write_pointer(MessageEncoder *self, void *value)
//@ requires ext_encoder(self, ?b, ?cap, ?c, ?k, ?copies) &*& (b == 0 || c + WORD_SIZE <= cap) &*& c + WORD_SIZE <= 1000;
//@ ensures ext_encoder(self, b, cap, c + WORD_SIZE, k, copies);
{
  //@ open ext_encoder(self, b, cap, c, k, copies);
  //@ if (b != 0) buf_take(b, c, WORD_SIZE);
  if (!MessageEncoder_encoding_for_size(self)) {
    memcpy((void *)&self->buffer_[self->cursor_], (void *)&value, (size_t)WORD_SIZE);
  }
  //@ if (b != 0) { chars_to_pointer(&value); buf_give(b, c, WORD_SIZE); }
  self->cursor_ += (word)WORD_SIZE;
  //@ close ext_encoder(self, b, cap, c + WORD_SIZE, k, copies);
}

// C++: src/messaging.cc toit::MessageEncoder::reserve_external
bool MessageEncoder_reserve_external(MessageEncoder *self)
//@ requires self->externals_count_ |-> ?k &*& self->too_many_externals_ |-> _;
/*@ ensures self->externals_count_ |-> (k < MESSAGING_ENCODING_MAX_EXTERNALS ? k + 1 : k) &*& self->too_many_externals_ |-> _ &*&
            result == (k < MESSAGING_ENCODING_MAX_EXTERNALS); @*/
{
  if (self->externals_count_ >= (unsigned int)MESSAGING_ENCODING_MAX_EXTERNALS) {
    self->too_many_externals_ = true;
    return false;
  }
  self->externals_count_++;
  return true;
}

// C++: src/messaging.cc toit::MessageEncoder::encode_bytes_external
bool MessageEncoder_encode_bytes_external(MessageEncoder *self, void *data, word length, bool free_on_failure)
/*@ requires ext_encoder(self, ?b, ?cap, ?c, ?k, ?copies) &*& k < MESSAGING_ENCODING_MAX_EXTERNALS &*& 0 <= length &*&
             c + 1 + 10 + WORD_SIZE <= 1000 &*& (b == 0 || c + 1 + card_len(length) + WORD_SIZE <= cap) &*&
             (b != 0 && free_on_failure ? block(data) : true); @*/
/*@ ensures ext_encoder(self, b, cap, c + 1 + card_len(length) + WORD_SIZE, k + 1,
                        (b != 0 && free_on_failure ? append(copies, cons(data, nil)) : copies)) &*& result; @*/
{
  //@ open ext_encoder(self, b, cap, c, k, copies);
  if (MessageEncoder_encoding_tison(self)) {
    return false;
  }
  if (!MessageEncoder_reserve_external(self)) {
    return false;
  }
  //@ close ext_encoder(self, b, cap, c, k + 1, copies);
  MessageEncoder_write_uint8(self, (uint8)TAG_BYTE_ARRAY);
  MessageEncoder_write_cardinal(self, (uword)length);
  MessageEncoder_write_pointer(self, data);
  //@ open ext_encoder(self, b, cap, ?c3, k + 1, copies);
  if (!MessageEncoder_encoding_for_size(self) && free_on_failure) {
    //@ open pointers_(self->copied_ + length(copies), _, _);
    //@ foreach_append_one(copies, data);
    self->copied_[self->copied_count_++] = data;
    //@ close pointers(self->copied_ + length(copies) + 1, 0, nil);
    //@ close pointers(self->copied_ + length(copies), 1, cons(data, nil));
    //@ pointers_join(self->copied_);
  }
  //@ close ext_encoder(self, b, cap, c3, k + 1, (b != 0 && free_on_failure ? append(copies, cons(data, nil)) : copies));
  return true;
}

// C++: src/messaging.cc toit::MessageEncoder::encode_rpc_reply_external
bool MessageEncoder_encode_rpc_reply_external(MessageEncoder *self, int id, bool is_exception, char *exception, void *data, word length, bool free_on_failure)
/*@ requires ext_encoder(self, ?b, ?cap, 0, 0, ?copies) &*& 0 <= id &*& 0 <= length &*&
             exc_str(is_exception, exception, ?fe, ?ecs) &*&
             (b == 0 || reply_size(id, is_exception, length(ecs), length) <= cap) &*&
             (!is_exception && b != 0 && free_on_failure ? block(data) : true); @*/
/*@ ensures exc_str(is_exception, exception, fe, ecs) &*&
            ext_encoder(self, b, cap, reply_size(id, is_exception, length(ecs), length), ?k2,
                        (!is_exception && b != 0 && free_on_failure ? append(copies, cons(data, nil)) : copies)) &*&
            result == (!is_exception || length(ecs) <= MESSAGING_ENCODING_MAX_INLINED_SIZE); @*/
{
  //@ open ext_encoder(self, b, cap, 0, 0, copies);
  if (MessageEncoder_encoding_tison(self)) {
    return false;
  }
  //@ close ext_encoder(self, b, cap, 0, 0, copies);
  MessageEncoder_write_uint8(self, (uint8)TAG_ARRAY);
  MessageEncoder_write_cardinal(self, (uword)(is_exception ? 4 : 3));
  MessageEncoder_write_uint8(self, (uint8)TAG_POSITIVE_SMI);
  MessageEncoder_write_cardinal(self, (uword)id);
  if (is_exception) {
    MessageEncoder_write_uint8(self, (uint8)TAG_TRUE);
    //@ open exc_str(is_exception, exception, fe, ecs);
    int exception_length = (int)strnlen(exception, (size_t)((int)MESSAGING_ENCODING_MAX_INLINED_SIZE + 1));
    if (exception_length > (int)MESSAGING_ENCODING_MAX_INLINED_SIZE) {
      /*@ close exc_str(is_exception, exception, fe, ecs); @*/
      return false;
    }
    MessageEncoder_write_uint8(self, (uint8)TAG_STRING_INLINE);
    MessageEncoder_write_cardinal(self, (uword)exception_length);
    //@ assert ext_encoder(self, b, cap, ?c4, 0, copies);
    //@ open ext_encoder(self, b, cap, c4, 0, copies);
    //@ if (b != 0) buf_take(b, c4, exception_length);
    //@ string_prefix(exception, exception_length);
    if (!MessageEncoder_encoding_for_size(self)) {
      memcpy((void *)&self->buffer_[self->cursor_], (void *)exception, (size_t)exception_length);
    }
    //@ if (b != 0) buf_give(b, c4, exception_length);
    //@ string_unprefix(exception, exception_length, ecs);
    self->cursor_ += (word)exception_length;
    //@ close ext_encoder(self, b, cap, c4 + exception_length, 0, copies);
    //@ close exc_str(is_exception, exception, fe, ecs);
    MessageEncoder_write_uint8(self, (uint8)TAG_NULL);
    return true;
  } else {
    MessageEncoder_write_uint8(self, (uint8)TAG_FALSE);
    return MessageEncoder_encode_bytes_external(self, data, length, free_on_failure);
  }
}

// C++: src/messaging.cc toit::MessageEncoder::~MessageEncoder
void MessageEncoder_dtor(MessageEncoder *self)
//@ requires ext_enc_end(self);
/*@ ensures self->process_ |-> _ &*& self->program_ |-> _ &*& self->format_ |-> _ &*& self->buffer_ |-> _ &*&
            self->take_ownership_of_buffer_ |-> _ &*& self->cursor_ |-> _ &*& self->external_bytes_ |-> _ &*&
            self->nesting_ |-> _ &*& self->problematic_class_id_ |-> _ &*& self->nesting_too_deep_ |-> _ &*&
            self->too_many_externals_ |-> _ &*& self->too_large_ |-> _ &*& self->over_limit_ |-> _ &*&
            self->max_total_size_ |-> _ &*& self->malloc_failed_ |-> _ &*& self->externals_count_ |-> _ &*&
            self->copied_count_ |-> _ &*& pointers_(self->copied_, MESSAGING_ENCODING_MAX_EXTERNALS, _) &*&
            self->transferred_count_ |-> _ &*& pointers_(self->transferred_, MESSAGING_ENCODING_MAX_EXTERNALS, _); @*/
{
  //@ open ext_enc_end(self);
  //@ assert self->copied_count_ |-> ?n &*& pointers(self->copied_, n, ?cps);
  for (unsigned int i = 0; i < self->copied_count_; i++)
  /*@ invariant self->copied_count_ |-> n &*& pointers(self->copied_, n, cps) &*& length(cps) == n &*&
                0 <= i &*& i <= n &*& foreach(drop(i, cps), block); @*/
  {
    //@ drop_n_plus_one(i, cps);
    //@ open foreach(drop(i, cps), block);
    //@ open block(nth(i, cps));
    free(self->copied_[i]);
  }
  //@ drop_all(cps, n);
  //@ open foreach(drop(n, cps), block);
  //@ pointers_pointers__join(self->copied_);
  if (self->take_ownership_of_buffer_) {
    free((void *)self->buffer_);
  }
}

// C++: src/messaging.cc toit::MessageEncoder::take_buffer
uint8 *MessageEncoder_take_buffer(MessageEncoder *self)
//@ requires ext_encoder(self, ?b, ?cap, ?c, ?k, ?copies);
/*@ ensures ext_encoder_taken(self, length(copies)) &*& result == b &*& foreach(copies, block) &*&
            (b == 0 ? true : malloc_block(b, cap) &*& uchars_(b, cap, _)); @*/
{
  //@ open ext_encoder(self, b, cap, c, k, copies);
  for (unsigned int i = 0; i < self->transferred_count_; i++)
  //@ invariant self->transferred_count_ |-> 0 &*& 0 <= i;
  {
    ByteArray *array = self->transferred_[i];
    ByteArray_neuter(array, self->process_);
    HeapObject_clear_has_active_finalizer(array);
  }
  for (unsigned int i = 0; i < self->copied_count_; i++)
  /*@ invariant self->copied_count_ |-> length(copies) &*& pointers(self->copied_, length(copies), ?cps) &*&
                0 <= i &*& i <= length(copies) &*& length(cps) == length(copies) &*&
                all_eq(take(i, cps), (void *)0) == true; @*/
  {
    //@ all_eq_take_update(cps, i);
    self->copied_[i] = 0;
  }
  uint8 *result = self->buffer_;
  self->buffer_ = 0;
  //@ assert pointers(self->copied_, length(copies), ?cps1);
  //@ take_all(cps1);
  //@ close ext_encoder_taken(self, length(copies));
  return result;
}

